; calls.asm -- chapter 12: a call inside a call inside a call
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "calls.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; A call inside a call inside a call. The console stops at third, three
; calls deep.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        ld bc, $1111
        call first
back0:  jr back0                ; back here at the end, for good
stop:   jr stop

first:  push bc                 ; the caller's BC kept on the stack
        ld bc, $2222
        call second
back1:  pop bc                  ; BC as the caller had it
        ret

second: call third
back2:  ret

third:  nop                     ; the console stops here
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
